  { json: { question: 'How can I contact support?', expected_keywords: ['support', 'contact', 'help'] } },
];

// Fixed-size recursive chunking with overlap.
var cfg = $('Workflow Configuration').first().json;
var size = Number(cfg.fixedChunkSize) || 1000;
var overlap = Number(cfg.fixedOverlap) || 200;
var maxChars = Number(cfg.maxCharsPerDoc) || 200000;
var fullText = '';
var ins = $input.all();
for (var i = 0; i < ins.length; i++) { fullText += '\n\n' + String(ins[i].json.text || ''); }
fullText = fullText.substring(0, maxChars);
var parts = [];
var paras = fullText.split(/\n\s*\n/);
for (var p = 0; p < paras.length; p++) {
  var para = paras[p];
  if (para.length <= size) { parts.push(para); continue; }
  var sents = para.match(/[^.!?]+[.!?]+/g) || [para];
  var cur = '';
  for (var s = 0; s < sents.length; s++) {
    if ((cur + ' ' + sents[s]).length > size && cur) { parts.push(cur); cur = sents[s]; }
    else { cur = cur ? cur + ' ' + sents[s] : sents[s]; }
  }
  if (cur) parts.push(cur);
}
var out = [], idx = 0;
for (var c = 0; c < parts.length; c++) {
  var txt = parts[c];
  if (overlap > 0 && c > 0) { txt = parts[c-1].substring(Math.max(0, parts[c-1].length - overlap)) + '\n' + txt; }
  if (txt.trim().length > 30) out.push({ json: { strategy: 'fixed-size', chunk_index: idx++, text: txt } });
}
return out;

// Embed every chunk with Gemini text-embedding-004 (free tier), 100 per call.
var cfg = $('Workflow Configuration').first().json;
var apiKey = String(cfg.geminiApiKey || '');
var chunks = $input.all().map(function(i){ return i.json; });
var embeds = [];
for (var b = 0; b < chunks.length; b += 100) {
  var batch = chunks.slice(b, b + 100);
  var resp = await $http.request({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/text-embedding-004:batchEmbedContents?key=' + apiKey,
    headers: { 'Content-Type': 'application/json' },
    body: { requests: batch.map(function(c){ return { model: 'models/text-embedding-004', content: { parts: [{ text: String(c.text).substring(0, 8000) }] } }; }) }
  });
  var data = (typeof resp === 'string') ? JSON.parse(resp) : resp;
  var embs = data.embeddings || [];
  for (var e = 0; e < embs.length; e++) { embeds.push(embs[e].values || []); }
}
for (var k = 0; k < chunks.length && k < embeds.length; k++) { chunks[k].embedding = embeds[k]; }
return chunks.map(function(c){ return { json: c }; });

// Load the test question set for this arm's evaluation loop.
var qs = $('Test Question Set').all().map(function(i){ return i.json; });
return qs.map(function(q){ return { json: q }; });

// Retrieve: embed the question, cosine-rank every chunk, return topK with context.
// The chunk node name is injected by the build script (Embed Chunks A).
var cfg = $('Workflow Configuration').first().json;
var apiKey = String(cfg.geminiApiKey || '');
var topK = Number(cfg.topK) || 4;
var q = $input.first().json;
var chunks = $('Embed Chunks A').all().map(function(i){ return i.json; });
var resp = await $http.request({
  method: 'POST',
  url: 'https://generativelanguage.googleapis.com/v1beta/models/text-embedding-004:embedContent?key=' + apiKey,
  headers: { 'Content-Type': 'application/json' },
  body: { model: 'models/text-embedding-004', content: { parts: [{ text: String(q.question).substring(0, 1500) }] } }
});
var data = (typeof resp === 'string') ? JSON.parse(resp) : resp;
var qv = (data.embedding && data.embedding.values) || [];
function cos(a, c) {
  var d = 0, na = 0, nc = 0;
  for (var k = 0; k < a.length; k++) { d += a[k]*c[k]; na += a[k]*a[k]; nc += c[k]*c[k]; }
  return (na === 0 || nc === 0) ? 0 : d / (Math.sqrt(na) * Math.sqrt(nc));
}
var scored = [];
for (var i = 0; i < chunks.length; i++) {
  if (!chunks[i].embedding || !chunks[i].embedding.length) continue;
  scored.push({ text: chunks[i].text, score: cos(qv, chunks[i].embedding) });
}
scored.sort(function(a, b){ return b.score - a.score; });
var top = scored.slice(0, topK);
return [{ json: {
  question: q.question,
  expected_keywords: q.expected_keywords || [],
  strategy: 'fixed-size',
  context: top.map(function(t){ return t.text; }).join('\n\n---\n\n'),
  chunks_used: top.length
} }];

