var apiKey = String(cfg.geminiApiKey || '');
var model = String(cfg.judgeModel || 'gemini-2.0-flash');
var r = $input.first().json;
async function gemini(prompt, jsonMode) {
  var body = { contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0 } };
  if (jsonMode) body.generationConfig.responseMimeType = 'application/json';
  var resp = await $http.request({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/' + model + ':generateContent?key=' + apiKey,
    headers: { 'Content-Type': 'application/json' },
    body: body
  });
  var data = (typeof resp === 'string') ? JSON.parse(resp) : resp;
  try { return data.candidates[0].content.parts[0].text; } catch (e) { return ''; }
}
