// Semantic chunking: sentence-split, batch-embed with Gemini (free tier),
// cut chunks where adjacent-sentence cosine similarity drops below (mean - 0.5*std).
var cfg = $('Workflow Configuration').first().json;
var apiKey = String(cfg.geminiApiKey || '');
