var sentences = (fullText.match(/[^.!?\n]+[.!?]+/g) || [fullText]).map(function(s){ return s.trim(); }).filter(function(s){ return s.length > 25; });
if (sentences.length < 3) { return [{ json: { strategy: 'semantic', chunk_index: 0, text: fullText } }]; }
var embeds = [];
for (var b = 0; b < sentences.length; b += 100) {
  var batch = sentences.slice(b, b + 100);
  var resp = await $http.request({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/text-embedding-004:batchEmbedContents?key=' + apiKey,
    headers: { 'Content-Type': 'application/json' },
    body: { requests: batch.map(function(s){ return { model: 'models/text-embedding-004', content: { parts: [{ text: s.substring(0, 1500) }] } }; }) }
  });
  var data = (typeof resp === 'string') ? JSON.parse(resp) : resp;
  var embs = data.embeddings || [];
  for (var e = 0; e < embs.length; e++) { embeds.push(embs[e].values || []); }
}
function cos(a, c) {
  var d = 0, na = 0, nc = 0;
  for (var k = 0; k < a.length; k++) { d += a[k]*c[k]; na += a[k]*a[k]; nc += c[k]*c[k]; }
  return (na === 0 || nc === 0) ? 0 : d / (Math.sqrt(na) * Math.sqrt(nc));
}
var sims = [];
for (var s2 = 0; s2 < embeds.length - 1; s2++) { sims.push(cos(embeds[s2], embeds[s2+1])); }
var mean = sims.reduce(function(a,c){return a+c;},0) / sims.length;
var variance = sims.reduce(function(a,c){return a + (c-mean)*(c-mean);},0) / sims.length;
var threshold = mean - 0.5 * Math.sqrt(variance);
var out = [], cur2 = [sentences[0]], idx2 = 0;
for (var s3 = 1; s3 < sentences.length; s3++) {
  if (sims[s3-1] < threshold && cur2.join(' ').length > 200) {
    out.push({ json: { strategy: 'semantic', chunk_index: idx2++, text: cur2.join(' ') } });
    cur2 = [sentences[s3]];
  } else { cur2.push(sentences[s3]); }
}
out.push({ json: { strategy: 'semantic', chunk_index: idx2, text: cur2.join(' ') } });
return out;

