// Each child carries a slice of its parent as context, so small precise chunks
// still retrieve with surrounding meaning attached.
var cfg = $('Workflow Configuration').first().json;
var parentSize = Number(cfg.parentChunkSize) || 2000;
var childSize = Number(cfg.childChunkSize) || 400;
