fullText = fullText.substring(0, maxChars);
var paras = fullText.split(/\n\s*\n/);
var parents = [], cur = '';
for (var p = 0; p < paras.length; p++) {
  if ((cur + '\n\n' + paras[p]).length > parentSize && cur.length > 0) { parents.push(cur); cur = paras[p]; }
  else { cur = cur ? cur + '\n\n' + paras[p] : paras[p]; }
}
if (cur) parents.push(cur);
var out = [], ci = 0;
for (var pi = 0; pi < parents.length; pi++) {
  var parent = parents[pi];
  for (var s = 0; s < parent.length; s += childSize) {
    var child = parent.substring(s, s + childSize);
    if (child.trim().length < 30) continue;
    out.push({ json: { strategy: 'parent-document', chunk_index: ci++, parent_index: pi,
      text: child + '\n\n[Parent context]\n' + parent.substring(0, 600) } });
  }
}
return out;

